import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String s = sc.next();
        int countSF = 0, countFS = 0;
        for (int i = 1; i < n; i++) {
            char prev = s.charAt(i - 1);
            char curr = s.charAt(i);
            if (prev == 'S' && curr == 'F') {
                countSF++;
            } else if (prev == 'F' && curr == 'S') {
                countFS++;
            }
        }
        System.out.println(countSF > countFS ? "YES" : "NO");
    }
}
